//! Raw bindings to the Tile IR linkage provider C ABI.
//!
//! A linkage provider is a shared object the Tile IR assembler loads while it
//! compiles a Tile kernel. The assembler looks up one symbol,
//! `tileir_create_linkage_provider`, receives a vtable, and then asks the
//! provider for implementation descriptions and for device code. This crate
//! is only the ABI: the structs, enums and callback signatures, generated by
//! bindgen from the compiler's own header at build time (see the crate
//! README for where the header comes from and why it is not vendored). The
//! runtime that implements the callbacks is `oxide-tile-provider`.
//!
//! Every C enum is a newtype over its integer representation, so a value the
//! header does not name is still representable; the header says such values
//! are protocol errors, and the runtime treats them that way.

#![allow(non_upper_case_globals, non_camel_case_types, non_snake_case)]
#![allow(clippy::missing_safety_doc, clippy::too_many_arguments)]
#![allow(unsafe_op_in_unsafe_fn)]

include!(concat!(env!("OUT_DIR"), "/bindings.rs"));

/// The ABI version this crate was generated from, as the vtable wants it.
pub const ABI_VERSION: TileIRLinkageProviderAPIVersion = TileIRLinkageProviderAPIVersion {
    major: TILEIR_LINKAGE_PROVIDER_API_VERSION_MAJOR,
    minor: TILEIR_LINKAGE_PROVIDER_API_VERSION_MINOR,
    patch: TILEIR_LINKAGE_PROVIDER_API_VERSION_PATCH,
};

/// The symbol a provider shared object exports, without the trailing NUL.
pub const ENTRY_SYMBOL: &str = "tileir_create_linkage_provider";

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_abi_version_is_the_pre_release_one() {
        assert_eq!(
            (ABI_VERSION.major, ABI_VERSION.minor, ABI_VERSION.patch),
            (0, 0, 1)
        );
    }

    #[test]
    fn the_entry_symbol_matches_the_header() {
        let header = std::ffi::CStr::from_bytes_with_nul(TILEIR_PROVIDER_ENTRY_SYMBOL).unwrap();
        assert_eq!(header.to_str().unwrap(), ENTRY_SYMBOL);
    }

    #[test]
    fn enums_are_newtypes_with_the_documented_values() {
        assert_eq!(TileIRLPResult::TILEIR_LP_SUCCESS.0, 0);
        assert_eq!(TileIRLPResult::TILEIR_LP_ERROR_UNRESOLVED_CALLS.0, 6);
        assert_eq!(TileIROutputType::TILEIR_OUTPUT_LTO_IR.0, 1);
        assert_eq!(TileIRLPRankDisposition::TILEIR_LP_RANK_SCORED.0, 2);
    }
}
